// #ab5503740f14ca6865210385 (#210385) — /admin/businesses соответствует Figma 812:448: точка статуса справа от текста,
// стрелка в конце строки, имена без подчёркивания, плюс слева от текста кнопки, полное боковое меню со значками.
// Кейс BIZ-LIST-002 · spec: specs/businesses-list.md (2.1) · seed: tests/seed.admin.spec.ts. Только чтение — @prod-safe.
import * as path from 'path';
import { test, expect } from '../../fixtures';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

test.describe('Список бизнесов — соответствие Figma 812:448 (#ab5503740f14ca6865210385)', () => {
  test('статус — точка справа от текста, стрелка в конце строки, имена без подчёркивания, плюс слева на кнопке, меню со значками @desktop @prod-safe #ab5503740f14ca6865210385', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto('/admin/businesses');
    await expect(page.getByRole('heading', { level: 1, name: 'בתי העסק' })).toBeVisible();
    const table = page.getByRole('table', { name: /^רשימת בתי העסק/ });
    const rows = table.locator('tbody').getByRole('row');
    await expect(rows.first()).toBeVisible();

    // Подзаголовок как в кадре.
    await expect(page.getByText(/^\d+ בתי עסק · \d+ פעילים · \d+ חסום\. אין הרשמה עצמאית: כל בית עסק נפתח מכאן\.$/)).toBeVisible();

    const geo = await rows.evaluateAll((trs) =>
      trs.map((tr) => {
        const cells = [...tr.querySelectorAll('td')];
        const statusCell = cells.find((td) => td.getAttribute('data-label') === 'סטטוס');
        const dot = statusCell?.querySelector('[aria-hidden="true"]') as HTMLElement | null;
        const text = dot?.nextElementSibling as HTMLElement | null;
        const name = cells[0]?.querySelector('a') as HTMLElement | null;
        const arrow = cells[cells.length - 1]?.querySelector('img, svg') as Element | null;
        const d = dot?.getBoundingClientRect();
        const t = text?.getBoundingClientRect();
        const a = arrow?.getBoundingClientRect();
        return {
          name: name?.textContent?.trim() || '',
          status: text?.textContent?.trim() || '',
          dot: d ? { w: Math.round(d.width), h: Math.round(d.height), left: d.left } : null,
          textRight: t ? t.right : null,
          underline: name ? getComputedStyle(name).textDecorationLine : 'no-link',
          arrow: a ? { w: Math.round(a.width), h: Math.round(a.height) } : null,
        };
      }),
    );
    expect(geo.length).toBeGreaterThan(0);
    for (const r of geo) {
      expect(r.status, `${r.name}: текст статуса`).toMatch(/^(פעיל|חסום)$/);
      expect(r.dot, `${r.name}: точка статуса`).toEqual(expect.objectContaining({ w: 8, h: 8 }));
      // Figma 812:448: точка СПРАВА от текста статуса (реджект 14.10 — была слева).
      expect(r.dot!.left, `${r.name}: точка справа от текста`).toBeGreaterThanOrEqual(r.textRight! - 0.5);
      expect(r.underline, `${r.name}: имя без подчёркивания`).toBe('none');
      expect(r.arrow, `${r.name}: стрелка в конце строки`).toEqual({ w: 20, h: 20 });
    }

    // Кнопка «יצירת בית עסק»: ≈169×44 (замер QA 21.10 — 170×44, допуск ±4 px), плюс СЛЕВА от текста.
    const create = page.getByRole('link', { name: 'יצירת בית עסק' });
    await expect(create).toHaveAttribute('href', '/admin/businesses/new');
    const btn = await create.evaluate((el) => {
      const r = el.getBoundingClientRect();
      const icon = el.querySelector('img, svg')!.getBoundingClientRect();
      const textNode = [...el.childNodes].find((n) => n.nodeType === Node.TEXT_NODE && n.textContent!.trim())!;
      const range = document.createRange();
      range.selectNodeContents(textNode);
      const t = range.getBoundingClientRect();
      return { w: r.width, h: r.height, iconRight: icon.right, iconW: Math.round(icon.width), textLeft: t.left };
    });
    expect(Math.abs(btn.w - 169), `ширина кнопки ${btn.w}`).toBeLessThanOrEqual(4);
    expect(Math.abs(btn.h - 44), `высота кнопки ${btn.h}`).toBeLessThanOrEqual(4);
    expect(btn.iconW).toBe(20);
    expect(btn.iconRight, 'плюс слева от текста').toBeLessThanOrEqual(btn.textLeft + 0.5);

    // Боковое меню как в кадре: 6 пунктов со значками (в т.ч. «בקשות מידע»), «התנתקות» со значком выхода.
    const nav = page.getByRole('navigation', { name: 'ניווט ראשי' });
    const items = ['בתי עסק', 'רישום גישה', 'תמיכה ותפעול', 'בקשות מידע', 'ספקי AI ותמלול', 'תבניות סימולציה'];
    await expect(nav.getByRole('link')).toHaveText(items);
    for (const item of items) await expect(nav.getByRole('link', { name: item }).locator('img, svg'), `значок «${item}»`).toHaveCount(1);
    await expect(nav.getByRole('link', { name: 'בקשות מידע' })).toHaveAttribute('href', '/admin/data-requests');
    await expect(page.getByRole('button', { name: 'התנתקות' }).locator('img, svg'), 'значок выхода').toHaveCount(1);
  });
});
